import { normalizeColoredRange } from './normalize-colored-ranges.js';
import { ColoredRange } from '../types/colored-range.js';

/**
 * Defines the items to render in a threshold legend
 */
export const buildLegendItemsFromRange = (
  ranges: ColoredRange[],
  defaultColor: string,
) => ranges.map((i) => normalizeColoredRange(i, defaultColor));
